  "anniversaire": {"pos": "n.m.", "s": "Birthday; anniversary.", "cog": "anniversary.", "ipa": "[a.ni.vɛʁ.sɛʁ]", "ph": "-aire = [ɛʁ].", "pi": "birthday and anniversary.", "et": "annus + versus.", "ex": [["C'est son anniversaire aujourd'hui.", "It's his birthday today."], ["Bon anniversaire !", "Happy birthday!"]], "co": [["fêter son anniversaire", "celebrate a birthday"], ["cadeau d'anniversaire", "birthday present"]], "sy": [["—", "—", "—"]], "fq": "Common.", "me": "year + turn.", "tr": {"en": "Tomorrow is my birthday.", "fr": "Demain, c'est mon anniversaire.", "alt": "C'est mon anniversaire demain.", "note": ""}},
